INSERT INTO gcal.gcal_events (event_id, calendar_id, summary, description, location, start_ts, end_ts, start_json, end_json, organizer_email, creator_email, attendees_json, status, visibility, transparency, rrule_json, recurring_event_id, original_start_json, sequence, created, updated, hangout_link, ical_uid, extras_json) VALUES ('evt_5c1a7e93b2d04f61a8e7b8', 'julia.lawson@harmonygames.co', 'Q4 product claims review', 'Agenda: Q4 product claims review. Proposed live-claim standard for sign-off at the review.
A claim may be marked Live only if, at the freeze, the feature is enabled for 100% of production players and either an active production config row or at least one completed production run or transaction exists for Domino Delights in the warehouse. A merged PR, a Linear Done, a store listing or a design doc is not evidence of live. A feature enabled for a positive subset of players (a flag or cohort below 100%) is Testing. Zero enablement with no completed production run is Not live.', NULL, '2025-09-29 15:00:00+00', '2025-09-29 15:30:00+00', '{"dateTime":"2025-09-29T15:00:00Z"}', '{"dateTime":"2025-09-29T15:30:00Z"}', 'leonard.hayes@harmonygames.co', 'leonard.hayes@harmonygames.co', '[{"email":"julia.lawson@harmonygames.co","organizer":false,"responseStatus":"needsAction","self":true},{"email":"leonard.hayes@harmonygames.co","organizer":true,"responseStatus":"accepted"},{"email":"brian.foster@harmonygames.co","organizer":false,"responseStatus":"needsAction"}]', 'confirmed', NULL, 'opaque', '[]', NULL, NULL, 1, '2025-09-25 18:00:00+00', '2025-09-26 10:00:00+00', 'https://meet.google.com/q4c-claims-rev', '5c1a7e93b2d04f61a8e7b8c9d0e1f2a3@hg4', NULL);
