INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time) VALUES ('f_5a1b2c3d4e5f60718293a4', 'Q4 Product Claims', 'julia.lawson@harmonygames.co', '["leonard.hayes@harmonygames.co"]', 'private', 'Q4 Product Claims
Owner: Julia Lawson
Status: all 13 items verified live with the owning teams as of 29 September.

1. Weekly Quests run every week.
2. Weekly Leaderboards are automated.
3. Win & Collect runs every day.
4. River Rush is live.
5. Axe Arena and Streak Fever are live.
6. Season Pass is live on Domino Delights (shipped in #1755, ticket ENG-2136).
7. Collectibles ship in October.
8. Rewarded ads and remove-ads IAP are live.
9. Five coin bundles and a starter pack are live in the shop.
10. Hero Offers rotate every 48 hours.
11. The live-ops event engine is live.
12. 5,000 handcrafted levels are live.
13. Domino Delights launched on 14 April 2025.

Also mention the internal-tooling appendix for the live-ops engine.', '[]', 'a1b2c3d4e5f6', 'f_5a1b2c3d4e5f60718293a4', '2025-09-29 09:00:00+00', '2025-09-30 15:40:00+00');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time) VALUES ('f_5a1b2c3d4e5f60718293a5', 'Q4 Product Claims - September list', 'julia.lawson@harmonygames.co', '["leonard.hayes@harmonygames.co"]', 'private', 'Q4 Product Claims
Owner: Julia Lawson
Status: all 9 items verified live with the owning teams as of 12 September.

1. Weekly Quests run every week.
2. Weekly Leaderboards are automated.
3. Win & Collect runs every day.
4. River Rush is live.
5. Axe Arena and Streak Fever are live.
6. Season Pass is live on Domino Delights (shipped in #1755, ticket ENG-2136).
7. Collectibles ship in October.
8. Rewarded ads and remove-ads IAP are live.
9. Five coin bundles and a starter pack are live in the shop.', '[]', 'a1b2c3d4e5f7', 'f_5a1b2c3d4e5f60718293a5', '2025-09-12 09:00:00+00', '2025-09-12 10:00:00+00');

