-- trello: wording authority, same-service decoy, April bundle card

INSERT INTO trello.trello_cards (id, name, "idBoard", "idList", "desc", pos, closed, due, "dueComplete", "idMembers_json", "idLabels_json", "idShort", "shortLink", "shortUrl", url, "dateLastActivity", cover_json, badges_json, start, "idAttachmentCover") VALUES ('68daad004f5e6d7a8b9c0d10', 'Q4 live-claim standard', '65eb4ec525346c8070ca638f', '6835c1b70b0ae1346ed78628', 'Live-claim standard (agreed at the Q4 review). A claim may be marked Live only if, at the freeze, the feature is enabled for 100% of production players and either an active production config row or at least one completed production run or transaction exists for Domino Delights in the warehouse. A merged PR, a Linear Done, a store listing or a design doc is not evidence of live. A feature enabled for a positive subset of players (a flag or cohort below 100%) is Testing. Zero enablement with no completed production run is Not live.', 512.0, false, NULL, false, '[]', '[]', NULL, NULL, NULL, NULL, '2025-09-29 16:00:00+00', 'null', '{"attachments":0,"attachmentsByType":{"trello":{"board":0,"card":0}},"checkItems":0,"checkItemsChecked":0,"checkItemsEarliestDue":null,"comments":0,"description":true,"due":null,"dueComplete":false,"externalSource":null,"fogbugz":"","lastUpdatedByAi":false,"location":false,"maliciousAttachments":0,"start":null,"votes":0}', NULL, NULL);
INSERT INTO trello.trello_cards (id, name, "idBoard", "idList", "desc", pos, closed, due, "dueComplete", "idMembers_json", "idLabels_json", "idShort", "shortLink", "shortUrl", url, "dateLastActivity", cover_json, badges_json, start, "idAttachmentCover") VALUES ('68d672304f5e6d7a8b9c0d11', 'External wording - product claims', '65eb4ec525346c8070ca638f', '6835c1b70b0ae1346ed78628', 'External wording rules. LIVE items may say live or available. TESTING items must say in testing and must not use live, available or launched. NOT_LIVE items are removed, not caveated. Numeric and date claims state the exact value in the register. Every retained claim names an owner.', 1024.0, false, NULL, false, '[]', '[]', NULL, NULL, NULL, NULL, '2025-09-26 11:00:00+00', 'null', '{"attachments":0,"attachmentsByType":{"trello":{"board":0,"card":0}},"checkItems":0,"checkItemsChecked":0,"checkItemsEarliestDue":null,"comments":0,"description":true,"due":null,"dueComplete":false,"externalSource":null,"fogbugz":"","lastUpdatedByAi":false,"location":false,"maliciousAttachments":0,"start":null,"votes":0}', NULL, NULL);
INSERT INTO trello.trello_cards (id, name, "idBoard", "idList", "desc", pos, closed, due, "dueComplete", "idMembers_json", "idLabels_json", "idShort", "shortLink", "shortUrl", url, "dateLastActivity", cover_json, badges_json, start, "idAttachmentCover") VALUES ('68d6735c4f5e6d7a8b9c0d12', 'Engineering release wording', '640643a3fd8f3ca308d9318e', '641359135e6148b9de0e076c', 'Engineering release wording: merged and deployed is shipped; anything shipped this quarter may be called launched. Use for internal release notes.', 2048.0, false, NULL, false, '[]', '[]', NULL, NULL, NULL, NULL, '2025-09-26 11:05:00+00', 'null', '{"attachments":0,"attachmentsByType":{"trello":{"board":0,"card":0}},"checkItems":0,"checkItemsChecked":0,"checkItemsEarliestDue":null,"comments":0,"description":true,"due":null,"dueComplete":false,"externalSource":null,"fogbugz":"","lastUpdatedByAi":false,"location":false,"maliciousAttachments":0,"start":null,"votes":0}', NULL, NULL);
