INSERT INTO confluence.confluence_pages (id, space_id, parent_id, title, body, body_format, status, version, author_id, created_at, updated_at) VALUES ('page_release_status_definitions', 'space_ENG', 'page_eng_home', 'Release Status Definitions', '<h2>Engineering release status</h2><p>A release is <strong>shipped</strong> when its pull request is merged to main and deployed to the production environment. Use this page for internal release tracking; it does not cover product claims or external wording.</p>', 'storage', 'current', 1, 'user_EMPLOYEE_0025', '2025-09-05T09:00:00Z', '2025-09-05T09:00:00Z');
INSERT INTO confluence.confluence_pages (id, space_id, parent_id, title, body, body_format, status, version, author_id, created_at, updated_at) VALUES ('page_external_messaging_guide', 'space_PROD', 'page_prod_home', 'External Messaging Guide', '<h2>Messaging guide</h2><p>Anything shipped this quarter may be described as live in external materials. Use launched for features that are in testing. Keep sentences short.</p>', 'storage', 'current', 1, 'user_EMPLOYEE_0016', '2025-09-08T09:00:00Z', '2025-09-08T09:00:00Z');
INSERT INTO confluence.confluence_pages (id, space_id, parent_id, title, body, body_format, status, version, author_id, created_at, updated_at) VALUES ('page_q4_product_narrative', 'space_PROD', 'page_prod_home', 'Q4 Product Narrative', '<h2>Q4 story</h2><p>One narrative across the live-ops engine, the internal admin tools and the player-facing product. The launch date is the April 14 date the team uses.</p>', 'storage', 'current', 1, 'user_EMPLOYEE_0038', '2025-09-22T09:00:00Z', '2025-09-22T09:00:00Z');
INSERT INTO confluence.confluence_pages (id, space_id, parent_id, title, body, body_format, status, version, author_id, created_at, updated_at) VALUES ('page_q4_claims_conflict_format', 'space_PROD', 'page_prod_home', 'Q4 Claims Conflict Format', '<h2>Conflict format</h2><p>If a claim''s sources disagree, write both sources in the conflict column and say which one governs. Do not silently pick one.</p>', 'storage', 'current', 1, 'user_EMPLOYEE_0005', '2025-09-29T16:00:00Z', '2025-09-29T16:00:00Z');
INSERT INTO confluence.confluence_pages (id, space_id, parent_id, title, body, body_format, status, version, author_id, created_at, updated_at) VALUES ('page_q4_product_claims', 'space_PROD', 'page_prod_home', 'Q4 Product Claims', '<h2>Status</h2><p>All 13 product claims are live. See the Q4 claims draft for the full list.</p>', 'storage', 'current', 1, 'user_EMPLOYEE_0005', '2025-09-29T10:00:00Z', '2025-09-29T10:00:00Z');

